,{"key":"cill_hjh35iq","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]}]}},{"name":"Single Door With Side Light","sort_order":80,"tree":{"key":"item_wg9htyp","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"utile","sashMaterialId":"utile","cillMaterialId":"utile","quantity":1},"children":[{"key":"paint_1yzwh8m","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isDoorMpls":true},"children":[]},{"key":"notes_x9cnlth","part_type":"notesPart","values":{},"children":[]},{"key":"price_wd4rb6b","part_type":"pricePart","values":{},"children":[]},{"key":"frame_htmdyu1","part_type":"assemblyFramePart","values":{"width":1699,"height":2199,"leftWidth":47,"rightWidth":47,"topHeight":47,"bottomHeight":37,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":26,"rakeFrame":false,"archHead":false,"toBeReplaced":true},"children":[{"key":"mull_s9p51fc","part_type":"mullionPart","values":{"offset":1005,"thicknessInFrame":41,"mullionStopSize":20},"children":[]},{"key":"doorleaf_4zya56f","part_type":"doorLeafPart","values":{"operation":"left_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":110,"leftWidth":110,"rightWidth":110,"bottomHeight":163,"bottomHeightExternal":170,"btmRailShapeId":"stepped","mechanicalClearanceTop":2,"mechanicalClearanceLeft":3,"mechanicalClearanceRight":3,"mechanicalClearanceBottom":3,"archHead":false,"toBeReplaced":true},"children":[{"key":"doorleaf_4zya56f_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"cas_e16oy9l","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":86,"bottomHeightExternal":93,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"cas_e16oy9l_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"cill_v7xpy14","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]}]}},{"name":"Single Door With Side Lights And Fanlights","sort_order":90,"tree":{"key":"item_srh5wux","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"utile","sashMaterialId":"utile","cillMaterialId":"utile","quantity":1},"children":[{"key":"paint_fmxizls","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isDoorMpls":true},"children":[]},{"key":"notes_b01g370","part_type":"notesPart","values":{},"children":[]},{"key":"price_g1e79bd","part_type":"pricePart","values":{},"children":[]},{"key":"frame_l895nyr","part_type":"assemblyFramePart","values":{"width":2249,"height":2599,"leftWidth":47,"rightWidth":47,"topHeight":47,"bottomHeight":37,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":26,"rakeFrame":false,"archHead":false,"toBeReplaced":true},"children":[{"key":"mull_tkd8nh3","part_type":"mullionPart","values":{"offset":534,"thicknessInFrame":41,"mullionStopSize":20},"children":[]},{"key":"mull_yh3xyr4","part_type":"mullionPart","values":{"offset":1580,"thicknessInFrame":41,"mullionStopSize":20},"children":[]},{"key":"trans_3c36dh9","part_type":"transomPart","values":{"offset":399,"thicknessInFrame":41,"transomStopSize":18,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"cas_zja9e2g","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"bottomHeightExternal":69,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"cas_zja9e2g_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"cas_kiw9yn0","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"bottomHeightExternal":69,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"cas_kiw9yn0_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"cas_pf9sndc","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"bottomHeightExternal":69,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"cas_pf9sndc_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"cas_3ivewet","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":86,"bottomHeightExternal":93,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"cas_3ivewet_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"doorleaf_5jq0f7s","part_type":"doorLeafPart","values":{"operation":"left_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":110,"leftWidth":110,"rightWidth":110,"bottomHeight":163,"bottomHeightExternal":170,"btmRailShapeId":"stepped","mechanicalClearanceTop":2,"mechanicalClearanceLeft":3,"mechanicalClearanceRight":3,"mechanicalClearanceBottom":3,"archHead":false,"toBeReplaced":true},"children":[{"key":"doorleaf_5jq0f7s_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"cas_1n6vunm","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":86,"bottomHeightExternal":93,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"cas_1n6vunm_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"cill_ueaqtbs","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]}]}}]'::jsonb;
  _row        record;
  _tree       jsonb;
  _wtype      text;
BEGIN
  SELECT id INTO _profile_id FROM public.default_profiles
  WHERE code = 'open_out_doors' AND is_active = TRUE;
  IF _profile_id IS NULL THEN
    RAISE EXCEPTION 'No active default_profiles row with code ''open_out_doors'' — the door profile must exist first';
  END IF;

  SELECT code INTO _door_code FROM public.reference_options
  WHERE category = 'product' AND lower(label) = 'french door' AND is_active
  ORDER BY sort_order LIMIT 1;
  IF _door_code IS NULL THEN
    RAISE EXCEPTION 'No active reference_options row with category ''product'' and label ''French Door'' — run: SELECT code, label FROM reference_options WHERE category = ''product'' ORDER BY sort_order;';
  END IF;

  -- A template that cannot be saved is worse than no template.
  IF NOT EXISTS (
    SELECT 1 FROM part_type_children
    WHERE parent_code = 'assemblyFramePart' AND child_code = 'doorLeafPart'
  ) THEN
    RAISE EXCEPTION 'A frame cannot hold a door leaf — run sql/step-bb1-single-door-containment.sql first';
  END IF;

  -- And a door with no sections prices no timber at all, which would look
  -- like a working template and quote hundreds of pounds short.
  IF NOT EXISTS (
    SELECT 1 FROM parts_catalogue WHERE part_code = 'Utile67x96' AND is_active
  ) THEN
    RAISE EXCEPTION 'The Utile stock sections are missing — run sql/step-az1-utile-section-parts.sql first';
  END IF;

  IF jsonb_array_length(_templates) <> 5 THEN
    RAISE EXCEPTION 'Expected 5 templates in this script, found %', jsonb_array_length(_templates);
  END IF;

  FOR _row IN
    SELECT * FROM jsonb_to_recordset(_templates) AS x(name text, sort_order int, tree jsonb)
  LOOP
    _tree := jsonb_set(_row.tree, '{values,product}', to_jsonb(_door_code), true);
    -- A drawing with a PAIR is a French Door; a single leaf is a Door.
    _wtype := CASE
      WHEN jsonb_path_exists(_row.tree, '$.**.part_type ? (@ == "frenchDoorPart")')
      THEN 'French Door' ELSE 'Door' END;

    IF EXISTS (SELECT 1 FROM public.drawing_templates WHERE name = _row.name) THEN
      UPDATE public.drawing_templates
      SET tree = _tree, default_profile_id = _profile_id, window_type = _wtype,
          sort_order = _row.sort_order, updated_at = now()
      WHERE name = _row.name;
      RAISE NOTICE 'Step BB-2: % updated in place', _row.name;
    ELSE
      INSERT INTO public.drawing_templates
        (name, family, group_name, window_type, default_profile_id, tree, sort_order, is_active)
      VALUES (_row.name, 'door', 'Open Out Doors', _wtype,
              _profile_id, _tree, _row.sort_order, TRUE);
      RAISE NOTICE 'Step BB-2: % created', _row.name;
    END IF;
  END LOOP;

  -- The tidy: the two Step AZ templates hold a French pair and were created
  -- with window_type 'Door'. Templates only — no drawing is touched.
  UPDATE public.drawing_templates
  SET window_type = 'French Door', updated_at = now()
  WHERE family = 'door'
    AND name IN ('French Doors', 'French Doors With Fanlight')
    AND window_type IS DISTINCT FROM 'French Door';
END $$;

COMMIT;

-- ── Checks ─────────────────────────────────────────────────────────────────

-- 1. All ten door templates, with Product and window_type. Expect every row
--    holding a pair to read 'French Door' and the four single doors 'Door'.
SELECT name, group_name, window_type, sort_order, is_active,
       tree #>> '{values,product}'  AS product_code,
       tree #>> '{values,quantity}' AS quantity,
       tree #>> '{values,sashMaterialId}' AS material,
       jsonb_path_exists(tree, '$.**.part_type ? (@ == "frenchDoorPart")') AS has_pair,
       jsonb_path_exists(tree, '$.**.part_type ? (@ == "doorLeafPart")')   AS has_single_leaf
FROM   public.drawing_templates
WHERE  family = 'door'
ORDER  BY sort_order;

-- 2. Each new template's shape. Expect:
--      Glazed Side Panels  1 pair, 0 leaves, 2 mullions, 0 transoms, 2 frame glass
--      Single Door         0 pairs, 1 leaf, 0 mullions, 0 transoms, 0 sashes
--      With Fanlight       1 leaf, 0 mullions, 1 transom, 1 sash
--      With Side Light     1 leaf, 1 mullion, 0 transoms, 1 sash
--      Side Lights + Fans  1 leaf, 2 mullions, 1 transom, 5 sashes
SELECT t.name,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "frenchDoorPart")'))   AS pairs,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "doorLeafPart")'))     AS single_leaves,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "mullionPart")'))      AS mullions,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "transomPart")'))      AS transoms,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "casementSashPart")')) AS casement_sashes,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "glassPart")'))        AS glass_parts
FROM   public.drawing_templates t
WHERE  t.name IN (
    'French Doors With Glazed Side Panels',
    'Single Door',
    'Single Door With Fanlight',
    'Single Door With Side Light',
    'Single Door With Side Lights And Fanlights'
)
ORDER  BY t.sort_order;

-- 3. The single door leaf's own values: clearances 2 / 3 / 3 / 3, sections
--    110 / 110 / 110 with a 163 bottom rail, Left Hand Hung, open out, and
--    archHead FALSE on every one of them.
SELECT t.name,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values ? (@.btmRailShapeId == "stepped" && @.mechanicalClearanceTop == 2).mechanicalClearanceLeft') v) AS leaf_side_clearance,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values ? (@.mechanicalClearanceTop == 2).operation') v)    AS leaf_operation,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values ? (@.mechanicalClearanceTop == 2).archHead') v)     AS leaf_arch_head,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values ? (@.mechanicalClearanceTop == 2).bottomHeight') v) AS leaf_bottom_rail
FROM   public.drawing_templates t
WHERE  t.name LIKE 'Single Door%'
ORDER  BY t.sort_order;

-- 4. The dividers and the fixed-sash rails: a FANLIGHT is 62, a SIDE light
--    86. Expect mullion offsets 1005 (side light), 534 / 1580 (both) and
--    619 / 2066 (template 28), transoms at 399.
SELECT t.name,
       (SELECT jsonb_agg(v ORDER BY v::text) FROM jsonb_path_query(t.tree, '$.**.values ? (@.mullionStopSize > 0).offset') v) AS mullion_offsets,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values ? (@.transomStopSize == 18).offset') v)               AS transom_offsets,
       (SELECT jsonb_agg(v ORDER BY v::text) FROM jsonb_path_query(t.tree, '$.**.values ? (@.operation == "fix").bottomHeight') v) AS fixed_sash_rails
FROM   public.drawing_templates t
WHERE  t.name IN (
    'French Doors With Glazed Side Panels',
    'Single Door With Fanlight',
    'Single Door With Side Light',
    'Single Door With Side Lights And Fanlights'
)
ORDER  BY t.sort_order;

-- 5. None of the five carries a stored surround or ironmongery list, and all
--    five are utile. Expect NULL, NULL, utile.
SELECT t.name,
       t.tree #> '{values,surroundLines}' AS surrounds,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.ironmongeryLines') v) AS ironmongery,
       t.tree #>> '{values,sashMaterialId}' AS material
FROM   public.drawing_templates t
WHERE  t.name IN (
    'French Doors With Glazed Side Panels',
    'Single Door',
    'Single Door With Fanlight',
    'Single Door With Side Light',
    'Single Door With Side Lights And Fanlights'
)
ORDER  BY t.sort_order;


